import AxeBuilder from "@axe-core/playwright";
import { expect, test, type Page } from "@playwright/test";
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";
import { animationsSettled } from "./animations";

// Reports generated by the CLI and opened from file://: a page with its trace, and one without.
const output = resolve(import.meta.dirname, ".output");
const withTrace = pathToFileURL(resolve(output, "bundle/index.html")).href;
const withoutTrace = pathToFileURL(resolve(output, "multi-cdn/index.html")).href;

const VIEWS = ["Connections", "Compression", "Render", "Critical path"] as const;

async function open(page: Page, url: string) {
  const errors: string[] = [];
  page.on("console", (msg) => msg.type() === "error" && errors.push(msg.text()));
  page.on("pageerror", (err) => errors.push(err.message));
  await page.goto(url);
  await expect(page.getByText(/^Step 1 \/ \d+$/)).toBeVisible();
  return errors;
}

const toggle = (page: Page) => page.getByRole("button", { name: "Toggle analysis" });
const details = (page: Page) => page.getByRole("region", { name: "Analysis details" });
const view = (page: Page, name: string) => page.getByRole("button", { name, exact: true });

async function axeViolations(page: Page) {
  await animationsSettled(page);
  const results = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"])
    .analyze();
  return results.violations.map((v) => ({
    id: v.id,
    nodes: v.nodes.map((n) => n.target.join(" ")).slice(0, 5),
  }));
}

test("the toolbar button opens the analysis, its views switch, and the link follows them", async ({
  page,
}) => {
  const errors = await open(page, withTrace);
  await toggle(page).click();
  await expect(toggle(page)).toHaveAttribute("aria-expanded", "true");
  await expect(view(page, "Connections")).toHaveAttribute("aria-pressed", "true");
  await expect.poll(() => new URL(page.url()).hash).toBe("#d=connections");

  await view(page, "Render").click();
  await expect(view(page, "Render")).toHaveAttribute("aria-pressed", "true");
  await expect(details(page).getByRole("table", { name: "LCP phases" })).toBeVisible();
  await expect.poll(() => new URL(page.url()).hash).toBe("#d=render");

  await page.getByRole("button", { name: "Close analysis" }).click();
  await expect(toggle(page)).toBeFocused();
  await expect.poll(() => new URL(page.url()).hash).toBe("");
  expect(errors).toEqual([]);
});

test("the digits 6 to 9 open each view, and a link reopens the one it names", async ({
  page,
  context,
}) => {
  await open(page, withTrace);
  for (const [key, name] of [
    ["6", "Connections"],
    ["7", "Compression"],
    ["8", "Render"],
    ["9", "Critical path"],
  ]) {
    await page.keyboard.press(key);
    await expect(view(page, name)).toHaveAttribute("aria-pressed", "true");
  }
  await page.keyboard.press("9");
  await expect(toggle(page)).toHaveAttribute("aria-expanded", "false");

  const fresh = await context.newPage();
  await open(fresh, `${withTrace}#d=compression`);
  await expect(view(fresh, "Compression")).toHaveAttribute("aria-pressed", "true");
  await expect(details(fresh).getByRole("table", { name: "Text responses by type" })).toBeVisible();
});

test("a page without a trace says what it lacks, and shows what its HAR infers", async ({
  page,
}) => {
  const errors = await open(page, `${withoutTrace}#d=render`);
  await expect(details(page)).toContainText(
    "No trace: the LCP and its phases come from a Chrome trace"
  );
  await expect(details(page)).toContainText("FCP n/a without a trace");
  await expect(details(page)).toContainText("5 resources · 65 KB · held the first paint 100 ms");
  await expect(
    details(page).getByRole("table", { name: "Render-blocking resources" })
  ).toBeVisible();

  await page.keyboard.press("9");
  await expect(details(page)).toContainText("5 chains");
  await expect(details(page).getByRole("table")).toHaveCount(5);

  await page.keyboard.press("6");
  await expect(details(page)).toContainText("6 hosts · 15 network requests");
  await expect(details(page)).toContainText("The document sent no Server-Timing header.");

  await page.keyboard.press("7");
  await expect(details(page)).toContainText("About 1.9 KB could be saved");
  await expect(details(page).getByRole("table", { name: "Gzip or deflate only" })).toContainText(
    "embed.js"
  );
  expect(errors).toEqual([]);
});

for (const scheme of ["light", "dark"] as const) {
  test(`every analysis view has no axe violations: ${scheme} theme`, async ({ browser }) => {
    const context = await browser.newContext({ colorScheme: scheme });
    const page = await context.newPage();
    await open(page, withoutTrace);
    await toggle(page).click();
    for (const name of VIEWS) {
      await view(page, name).click();
      await expect(view(page, name)).toHaveAttribute("aria-pressed", "true");
      expect(await axeViolations(page), name).toEqual([]);
    }
    await context.close();
  });
}

test("forced colors draw the pressed view with the system highlight", async ({ browser }) => {
  const context = await browser.newContext({ forcedColors: "active" });
  const page = await context.newPage();
  await open(page, withTrace);
  await page.keyboard.press("7");
  const pressed = view(page, "Compression");
  const other = view(page, "Render");
  const colors = (el: typeof pressed) =>
    el.evaluate((node) => getComputedStyle(node).backgroundColor);
  expect(await colors(pressed)).not.toEqual(await colors(other));
  await context.close();
});

test.describe("on a phone", () => {
  test.use({ viewport: { width: 360, height: 740 }, hasTouch: true, reducedMotion: "reduce" });

  test("the button fits, the drawer takes the screen below the toolbar and its tables scroll inside it", async ({
    page,
  }) => {
    await open(page, withoutTrace);
    const button = (await toggle(page).boundingBox())!;
    expect(button.x).toBeGreaterThanOrEqual(0);
    expect(button.x + button.width).toBeLessThanOrEqual(360);
    expect(button.height).toBeGreaterThanOrEqual(44);

    await toggle(page).tap();
    const region = details(page);
    await expect(region).toBeVisible();
    const box = (await region.boundingBox())!;
    expect(box.y).toBeGreaterThanOrEqual(button.y + button.height);
    expect(box.x + box.width).toBeLessThanOrEqual(360 + 1);
    expect(await region.evaluate((el) => el.scrollWidth > el.clientWidth)).toBe(false);
    for (const name of VIEWS) {
      const chip = (await view(page, name).boundingBox())!;
      expect(chip.height, name).toBeGreaterThanOrEqual(24);
      expect(chip.x + chip.width, name).toBeLessThanOrEqual(360);
    }
    // A table wider than the screen scrolls inside its own box; the page never scrolls sideways.
    const table = region.getByRole("table", { name: "Connections per host" });
    const scroller = table.locator("xpath=..");
    expect(await scroller.evaluate((el) => el.scrollWidth > el.clientWidth)).toBe(true);
    expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(
      360
    );
  });
});
